// Vectors generated by a Rust test against `snow` (protocol/noise-vectors.json).
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { HandshakeState, KK_PATTERN, XXPSK3_PATTERN, keypairFromPrivate } from '../handshake';
import { Transport } from '../transport';
import { fromHex, nodeRng, toHex } from '../../../test-support/util';

interface Step {
  from: 'initiator' | 'responder';
  payload: string;
  ciphertext: string;
}
interface Vector {
  protocol_name: string;
  prologue: string;
  init_static: string;
  resp_static: string;
  init_ephemeral: string;
  resp_ephemeral: string;
  psk?: string;
  handshake_hash: string;
  messages: { payload: string; ciphertext: string }[];
  rekey_interval: number;
  transport: Step[];
}

const vectors: Vector[] = JSON.parse(
  readFileSync(path.join(__dirname, '../../../../protocol/noise-vectors.json'), 'utf8'),
).vectors;

const PATTERNS = { [KK_PATTERN.name]: KK_PATTERN, [XXPSK3_PATTERN.name]: XXPSK3_PATTERN };

describe('snow-generated vectors', () => {
  test('both protocol names are covered', () => {
    expect(vectors.map((v) => v.protocol_name).sort()).toEqual([KK_PATTERN.name, XXPSK3_PATTERN.name]);
  });

  for (const v of vectors) {
    test(`${v.protocol_name}: handshake and transport (with rekey every ${v.rekey_interval})`, () => {
      const pattern = PATTERNS[v.protocol_name];
      const initKp = keypairFromPrivate(fromHex(v.init_static));
      const respKp = keypairFromPrivate(fromHex(v.resp_static));
      const psk = v.psk ? fromHex(v.psk) : undefined;
      const isKK = pattern === KK_PATTERN;
      const init = new HandshakeState({
        pattern,
        role: 'initiator',
        rng: nodeRng,
        s: initKp,
        rs: isKK ? respKp.publicKey : undefined,
        psk,
        prologue: fromHex(v.prologue),
        ephemeralForTestingOnly: fromHex(v.init_ephemeral),
      });
      const resp = new HandshakeState({
        pattern,
        role: 'responder',
        rng: nodeRng,
        s: respKp,
        rs: isKK ? initKp.publicKey : undefined,
        psk,
        prologue: fromHex(v.prologue),
        ephemeralForTestingOnly: fromHex(v.resp_ephemeral),
      });

      v.messages.forEach((m, i) => {
        const [w, r] = i % 2 === 0 ? [init, resp] : [resp, init];
        const ct = w.writeMessage(fromHex(m.payload));
        expect(toHex(ct)).toBe(m.ciphertext);
        expect(toHex(r.readMessage(ct))).toBe(m.payload);
      });
      expect(toHex(init.handshakeHash())).toBe(v.handshake_hash);
      expect(toHex(resp.handshakeHash())).toBe(v.handshake_hash);

      const a = init.split();
      const b = resp.split();
      const it = new Transport(a.send, a.recv, v.rekey_interval);
      const rt = new Transport(b.send, b.recv, v.rekey_interval);
      expect(v.transport.length).toBeGreaterThan(v.rekey_interval * 2);
      for (const step of v.transport) {
        const [w, r] = step.from === 'initiator' ? [it, rt] : [rt, it];
        const ct = w.encrypt(fromHex(step.payload));
        expect(toHex(ct)).toBe(step.ciphertext);
        expect(toHex(r.decrypt(ct))).toBe(step.payload);
      }
    });
  }
});
